"use strict";

var ENGINE = ENGINE || {};
ENGINE.property = {
  init: function init() {}
};
var ENGINE = ENGINE || {};
ENGINE.common = {
  init: function init() {
    /* ホバー時にクラス付与 */
    var $nav = $('.js_navi');
    var navScrollTop = $nav.scrollTop();
    $nav.scroll(function () {
      navScrollTop = $nav.scrollTop();
    }); // change / colour のhover処理

    $(document).on('mouseover', '.js_hover', function (e) {
      $nav.css({
        'top': '-' + navScrollTop + 'px'
      });
      $('body').addClass('is_hover');
    });
    $(document).on('mouseout', '.js_hover', function (e) {
      $('body').removeClass('is_hover');
      $nav.css({
        'top': '0px'
      });
    });
    $(document).on('click', '.js_hover', function (e) {
      $('body').removeClass('is_hover');
      $nav.css({
        'top': '0px'
      });
    }); // 左ナビ Favarite の処理

    $('.js_favorite__btn').click(function () {
      $('.js_favorite__box').addClass('is_show');
      $('.js_favorite__cont').addClass('is_show');
      return false;
    });
    $('.js_favorite__close').click(function () {
      $('.js_favorite__box').removeClass('is_show');
      $('.js_favorite__cont').removeClass('is_show');
      return false;
    });
    /* デバイス高さ見切れる時、要素に高さを追加 */

    $(window).on('load resize', function () {
      var winH = $(window).height() - 100;
      $('.js_device-winH').css({
        'max-height': winH + 'px'
      });
    });
  }
};

ENGINE.log = function (obj) {
  console.log(obj);
};

var ENGINE = ENGINE || {};
ENGINE.smoothscroll = {
  init: function init() {
    $('body').on('click', 'a[href^="#"].js_smoothScroll', function () {
      // スクロールの速度
      var speed = 400; // Headerの高さ取得

      var headerHeight = $('.js_flow_nav').outerHeight(); // アンカーの値取得

      var href = $(this).attr("href"); // 移動先を取得

      var target = $(href);
      var adj = headerHeight + 20;
      var win_w = $(window).width();

      if (win_w < 768) {
        adj = 15;
      } // 移動先を数値で取得


      var headerPos = target.offset().top - adj;
      $('body,html').animate({
        scrollTop: headerPos
      }, speed, 'swing');
      return false;
    });
  }
};
/* ============================================
   モーダル
============================================ */

ENGINE.modal = {
  init: function init() {
    $('.js_modal__btn').on('click', function () {
      $('.js_modal').fadeIn();
      return false;
    });
    $('.js_modal__close').on('click', function () {
      $('.js_modal').fadeOut();
      return false;
    });
  }
};
var ENGINE = ENGINE || {};
ENGINE.matchHeight = {
  init: function init() {
    $('.js_matchHeight .js_matchHeight__item').matchHeight({
      byRow: true
    });
  }
};
window.addEventListener('DOMContentLoaded', function () {
  ENGINE.property.init();
  ENGINE.common.init();
  ENGINE.smoothscroll.init();
  ENGINE.modal.init();
  ENGINE.matchHeight.init();
});